'use strict';
const clipTransitionTypes=[['crossfade','Crossfade'],['slide-left','Slide left'],['slide-right','Slide right'],['zoom','Zoom'],['blur','Blur dissolve'],['flash','White flash']];
const transitionLooks=[['none','Original'],['warm','Warm'],['mono','Black & white'],['vivid','Vivid'],['soft','Soft']];
let chosenClipTransition='crossfade',chosenClipLook='warm';
function adjacentClips(o){return current().objects.filter(next=>next.id!==o?.id&&['image','video'].includes(next.type)&&Math.abs(clipStart(next)-clipEnd(o))<=1/30+.001)}
function exitClipPair(o,t=time){const spec=o.exitTransition;if(!spec||!['image','video'].includes(o.type))return null;const next=adjacentClips(o).find(n=>n.id===spec.toId);if(!next||next.hidden)return null;const duration=Math.min(spec.duration,clipEnd(o)-clipStart(o)),start=clipEnd(o)-duration;if(t<start||t>=clipEnd(o))return null;return{next,spec,f:clamp((t-start)/duration,0,1)}}
const clipSurfaceMap=new Map();function clipTransitionSurface(name){let canvas=clipSurfaceMap.get(name);if(!canvas){canvas=document.createElement('canvas');clipSurfaceMap.set(name,canvas)}if(canvas.width!==$('stage').width)canvas.width=$('stage').width;if(canvas.height!==$('stage').height)canvas.height=$('stage').height;return canvas}
const videoBeforeClipTransition=drawVideoObject,propBeforeClipTransition=prop;
function paintTransitionLayer(canvas,o,t){const c=canvas.getContext('2d');c.save();c.setTransform(canvas.width/960,0,0,canvas.height/540,0,0);c.clearRect(0,0,960,540);c.globalAlpha=1;c.filter='none';const v=stateAt(o,t);applyVisualEffects(c,o,v,t);withSceneTime(current(),t,()=>{if(o.type==='video')videoBeforeClipTransition(c,o,v);else propBeforeClipTransition(c,o,v)});c.restore()}
function paintClipTransition(c,o,pair){const {next,spec}=pair,intensity=spec.intensity??1,raw=clamp((pair.f-(1-intensity)/2)/Math.max(.001,intensity),0,1),f=raw*raw*(3-2*raw),out=clipTransitionSurface('out'),incoming=clipTransitionSurface('in'),result=clipTransitionSurface('mix');paintTransitionLayer(out,o,time);paintTransitionLayer(incoming,next,clipStart(next));const mix=result.getContext('2d');mix.save();mix.setTransform(result.width/960,0,0,result.height/540,0,0);mix.clearRect(0,0,960,540);mix.globalAlpha=1;mix.filter='none';if(spec.type==='slide-left'||spec.type==='slide-right'){const direction=spec.type==='slide-left'?-1:1;mix.drawImage(out,direction*960*f,0,960,540);mix.drawImage(incoming,-direction*960*(1-f),0,960,540)}else if(spec.type==='flash'){if(f<.5){mix.drawImage(out,0,0,960,540);mix.globalAlpha=f*2*intensity;rect(mix,0,0,960,540,'#ffffff')}else{mix.drawImage(incoming,0,0,960,540);mix.globalAlpha=(1-f)*2*intensity;rect(mix,0,0,960,540,'#ffffff')}}else{mix.globalAlpha=1-f;if(spec.type==='blur')mix.filter='blur('+(f*10)+'px)';if(spec.type==='zoom'){mix.save();mix.translate(480,270);mix.scale(1-.15*f*intensity,1-.15*f*intensity);mix.drawImage(out,-480,-270,960,540);mix.restore()}else mix.drawImage(out,0,0,960,540);mix.globalCompositeOperation='lighter';mix.globalAlpha=f;mix.filter=spec.type==='blur'?'blur('+((1-f)*10)+'px)':'none';if(spec.type==='zoom'){mix.translate(480,270);mix.scale(1+.2*(1-f)*intensity,1+.2*(1-f)*intensity);mix.drawImage(incoming,-480,-270,960,540)}else mix.drawImage(incoming,0,0,960,540)}mix.restore();c.save();c.filter='none';c.globalAlpha=1;c.drawImage(result,0,0,960,540);c.restore()}
drawVideoObject=function(c,o,v){const pair=exitClipPair(o);if(pair)return paintClipTransition(c,o,pair);return videoBeforeClipTransition(c,o,v)};
prop=function(c,o,v){if(o.type==='image'){const pair=exitClipPair(o);if(pair)return paintClipTransition(c,o,pair)}return propBeforeClipTransition(c,o,v)};
const videoSyncBeforeClipTransitions=syncVideoMedia;syncVideoMedia=function(){videoSyncBeforeClipTransitions();for(const o of current().objects){const pair=exitClipPair(o);if(!pair||pair.next.type!=='video')continue;const video=videoFor(pair.next);video.pause();if(video.readyState>=2&&!video.seeking&&Math.abs(video.currentTime-pair.next.sourceOffset)>.015)video.currentTime=pair.next.sourceOffset}};
document.querySelector('.studio-toolbar').insertAdjacentHTML('afterbegin','<button id="openClipEffects">Transitions & effects</button>');
document.body.insertAdjacentHTML('beforeend',`<dialog id="clipEffectsDialog"><div class="tool-heading"><div><div class="eyebrow">BUILT INTO ELLESON STUDIO</div><h2>Transitions & visual effects</h2></div><button id="closeClipEffects">Close</button></div><p class="note">These effects are included in the app. Select a clip, choose an effect and apply it.</p><div class="effect-tabs"><button id="showClipTransitions" class="active">Between clips</button><button id="showClipLooks">Clip looks</button></div><section id="clipTransitionPage"><div class="pro-tool-row"><label>From clip<select id="transitionFromClip"></select></label><label>To clip<select id="transitionToClip"></select></label><label>Duration (s)<input id="clipTransitionLength" type="number" min="0.1" max="3" step="0.1" value="0.5"></label></div><div id="clipTransitionCards" class="effect-card-grid"></div><p class="note">Place image or video clips end-to-start in the same scene. The outgoing clip's final section reveals the next clip's opening frame; scene and audio timing stay fixed.</p><div class="pro-tool-row"><button id="applyClipTransition" class="primary">Apply transition</button><button id="removeClipTransition">Remove transition</button><button id="previewClipTransition">Preview at transition</button></div><p id="clipTransitionStatus" class="note"></p></section><section id="clipLookPage" hidden><div id="clipLookCards" class="effect-card-grid"></div><p class="note">Looks change selected layers' color and contrast. They work with cropping, color key, fades and transitions.</p><button id="applyClipLook" class="primary">Apply look to selected layers</button></section></dialog>`);
function renderTransitionTargets(){const from=current().objects.find(o=>o.id===$('transitionFromClip').value),select=$('transitionToClip');select.replaceChildren();for(const o of from?adjacentClips(from):[]){const option=document.createElement('option');option.value=o.id;option.textContent=o.name;select.append(option)}if(from?.exitTransition)select.value=from.exitTransition.toId;$('applyClipTransition').disabled=!from||!!from.locked||!select.value;$('removeClipTransition').disabled=!from||!!from.locked||!from.exitTransition;$('previewClipTransition').disabled=!from?.exitTransition;$('clipTransitionStatus').textContent=select.options.length?'Ready to connect these clips.':'No adjacent clip yet. Trim or move another image/video so it starts when this clip ends.';if(from?.exitTransition){chosenClipTransition=from.exitTransition.type;$('clipTransitionLength').value=from.exitTransition.duration}renderEffectCards()}
function renderEffectCards(){for(const[id,items,value,set]of[['clipTransitionCards',clipTransitionTypes,chosenClipTransition,v=>chosenClipTransition=v],['clipLookCards',transitionLooks,chosenClipLook,v=>chosenClipLook=v]]){const grid=$(id);grid.replaceChildren();for(const[type,name]of items){const button=document.createElement('button');button.className='effect-card '+type+(value===type?' active':'');button.dataset.effect=type;const graphic=document.createElement('span');graphic.className='effect-swatch';graphic.textContent=id==='clipTransitionCards'?'A → B':'Aa';const label=document.createElement('strong');label.textContent=name;button.append(graphic,label);button.onclick=()=>{set(type);renderEffectCards()};grid.append(button)}}}
function applyExitTransition(o,next,type,duration){if(!o||!next||o.locked)return toast('Select an unlocked outgoing clip.');if(!adjacentClips(o).some(n=>n.id===next.id))return toast('Place the two clips end-to-start before applying a transition.');o.exitTransition={toId:next.id,type,duration:clamp(duration,.1,Math.min(3,clipEnd(o)-clipStart(o))),intensity:typeof $('clipTransitionIntensity')?.value==='string'?+$('clipTransitionIntensity').value/100:1};save();render();toast('Clip transition added. It is included in preview and export.')}
$('openClipEffects').onclick=()=>{stop();const selectedObject=object(),media=current().objects.filter(o=>['image','video'].includes(o.type)),select=$('transitionFromClip');select.replaceChildren();for(const o of media){const option=document.createElement('option');option.value=o.id;option.textContent=o.name;select.append(option)}const previous=media.find(o=>adjacentClips(o).some(n=>n.id===selectedObject?.id));select.value=selectedObject&&adjacentClips(selectedObject).length?selectedObject.id:previous?.id||selectedObject?.id||media[0]?.id||'';renderTransitionTargets();$('clipEffectsDialog').showModal()};$('closeClipEffects').onclick=()=>$('clipEffectsDialog').close();$('transitionFromClip').onchange=renderTransitionTargets;$('transitionToClip').onchange=()=>{$('applyClipTransition').disabled=!$('transitionToClip').value||!!current().objects.find(o=>o.id===$('transitionFromClip').value)?.locked};$('applyClipTransition').onclick=()=>{applyExitTransition(current().objects.find(o=>o.id===$('transitionFromClip').value),current().objects.find(o=>o.id===$('transitionToClip').value),chosenClipTransition,+$('clipTransitionLength').value||.5);renderTransitionTargets()};$('removeClipTransition').onclick=()=>{const o=current().objects.find(o=>o.id===$('transitionFromClip').value);if(!o||o.locked)return;delete o.exitTransition;save();render();renderTransitionTargets()};$('previewClipTransition').onclick=()=>{const o=current().objects.find(o=>o.id===$('transitionFromClip').value);if(!o?.exitTransition)return;time=clipEnd(o)-Math.min(o.exitTransition.duration,clipEnd(o)-clipStart(o))/2;selectLayers([o.id]);$('clipEffectsDialog').close();render()};
$('showClipTransitions').onclick=()=>{$('clipTransitionPage').hidden=false;$('clipLookPage').hidden=true;$('showClipTransitions').classList.add('active');$('showClipLooks').classList.remove('active')};$('showClipLooks').onclick=()=>{$('clipTransitionPage').hidden=true;$('clipLookPage').hidden=false;$('showClipTransitions').classList.remove('active');$('showClipLooks').classList.add('active')};$('applyClipLook').onclick=()=>{const list=selectedLayers();if(!list.length)return toast('Select a layer to apply a visual effect.');if(list.some(o=>o.locked))return toast('Unlock selected layers before applying an effect.');list.forEach(o=>o.look=chosenClipLook);save();render();toast('Visual effect applied to selected layers.')};
const timelineBeforeClipTransitions=renderTimeline;renderTimeline=function(){timelineBeforeClipTransitions();if(timelineDrag)return;const layers=current().objects.slice().reverse();document.querySelectorAll('.timeline-clip:not(.audio):not(.caption):not(.scene)').forEach((clip,index)=>{const o=layers[index];if(!o?.exitTransition)return;const pair=adjacentClips(o).some(n=>n.id===o.exitTransition.toId),badge=document.createElement('button');badge.className='clip-transition-badge'+(pair?'':' inactive');badge.textContent='↔';badge.title=pair?'Edit '+o.exitTransition.type+' transition':'Transition inactive: align the next clip';badge.onpointerdown=e=>e.stopPropagation();badge.onclick=()=>{selectLayers([o.id]);renderControls();$('openClipEffects').click()};clip.append(badge)})};
const clipEffectsValidator=valid;valid=function(p){return clipEffectsValidator(p)&&p.scenes.every(s=>s.objects.every(o=>!o.exitTransition||typeof o.exitTransition.toId==='string'&&o.exitTransition.toId.length<=160&&clipTransitionTypes.some(([type])=>type===o.exitTransition.type)&&Number.isFinite(o.exitTransition.duration)&&o.exitTransition.duration>=.1&&o.exitTransition.duration<=3&&(o.exitTransition.intensity===undefined||Number.isFinite(o.exitTransition.intensity)&&o.exitTransition.intensity>=0&&o.exitTransition.intensity<=1)))};
render();
